const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'G' },
      { kind: 'text', payload: 'N' },
      { kind: 'text', payload: 'f' },
      { kind: 'text', payload: '30°' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var A = Math.PI / 6;
    var c = Math.cos(A);
    var sn = Math.sin(A);
    var COL = '#26354A';
    var CG = '#B03A2E';
    var CN = '#1F6FB2';
    var CF = '#1E7B4A';
    var paths = [];
    var children = [];

    function addPath(id, cmds, fill, strokeWidth, dash) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id, fill: fill };
      if (strokeWidth) {
        node.stroke = { width: strokeWidth };
        if (dash) { node.stroke.dash = dash; }
      }
      children.push(node);
    }

    function addLabel(idx, x, y, ha, va, color) {
      children.push({
        type: 'label',
        contentId: metrics[idx].contentId,
        anchor: { x: x, y: y },
        hAlign: ha,
        vAlign: va,
        color: color
      });
    }

    function addArrow(id, sx, sy, ex, ey, color) {
      var dx = ex - sx;
      var dy = ey - sy;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      dx = dx / len;
      dy = dy / len;
      var hl = Math.min(16, len * 0.2);
      var hw = hl * 0.5;
      var bx = ex - hl * dx;
      var by = ey - hl * dy;
      var px = -dy;
      var py = dx;
      addPath(id + '-shaft', [['M', sx, sy], ['L', bx, by]], color, 2.6);
      addPath(id + '-head', [
        ['M', ex, ey],
        ['L', bx + hw * px, by + hw * py],
        ['L', bx - hw * px, by - hw * py],
        ['Z']
      ], color, 0);
    }

    var ABX = W * 0.14;
    var ABY = H * 0.86;
    var L = Math.min(W * 0.66, (H * 0.62) / sn);
    var TX = ABX + L * c;
    var TY = ABY - L * sn;

    addPath('surface', visualSdk.polyline([[ABX, ABY], [TX, TY]]), COL, 3);
    addPath('base', visualSdk.polyline([[ABX - W * 0.02, ABY], [ABX + L * c * 0.62, ABY]]), COL, 1.4, [7, 6]);

    var r = Math.min(L * 0.2, 74);
    var arcPts = [];
    for (var i = 0; i <= 12; i++) {
      var t = A * i / 12;
      arcPts.push([ABX + r * Math.cos(t), ABY - r * Math.sin(t)]);
    }
    addPath('arc', visualSdk.polyline(arcPts), COL, 1.6);
    addLabel(3, ABX + (r + 22) * Math.cos(A / 2), ABY - (r + 22) * Math.sin(A / 2), 'left', 'middle', COL);

    var s = Math.min(W, H) * 0.17;
    var half = s / 2;
    var px0 = ABX + L * 0.42 * c;
    var py0 = ABY - L * 0.42 * sn;
    var nx = -sn;
    var ny = -c;
    var CX = px0 + half * nx;
    var CY = py0 + half * ny;

    var corners = [[1, 1], [1, -1], [-1, -1], [-1, 1]];
    var cmds = [];
    for (var k = 0; k < corners.length; k++) {
      var a = corners[k][0];
      var b = corners[k][1];
      var qx = CX + a * half * c + b * half * nx;
      var qy = CY + a * half * (-sn) + b * half * ny;
      cmds.push([k === 0 ? 'M' : 'L', qx, qy]);
    }
    cmds.push(['Z']);
    addPath('block-fill', cmds, '#EDF1F6', 0);
    addPath('block-edge', cmds, COL, 2.4);

    var La = s * 1.55;
    var gTipX = CX;
    var gTipY = CY + La;
    var nTipX = CX + La * nx;
    var nTipY = CY + La * ny;
    var fTipX = CX + La * c;
    var fTipY = CY - La * sn;

    addArrow('g', CX, CY, gTipX, gTipY, CG);
    addArrow('n', CX, CY, nTipX, nTipY, CN);
    addArrow('f', CX, CY, fTipX, fTipY, CF);

    addLabel(0, gTipX, gTipY + 26, 'center', 'top', CG);
    addLabel(1, nTipX + nx * 24, nTipY + ny * 24, 'center', 'middle', CN);
    addLabel(2, fTipX + c * 24, fTipY - sn * 24, 'center', 'middle', CF);

    return {
      schemaVersion: 1,
      sceneId: 'incline-fbd',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
